import{_ as t}from"./chunks/c942050f3632721194f7.BjNs8BRl.js";import{_ as o,o as a,c as n,a6 as i}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"Why You Struggle To Make Money (and 7 Lessons To Change That)","description":"","frontmatter":{"title":"Why You Struggle To Make Money (and 7 Lessons To Change That)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that.md","filePath":"en/letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that.md"}'),r={name:"en/letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that.md"};function s(l,e,h,p,u,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="why-you-struggle-to-make-money-and-7-lessons-to-change-that" tabindex="-1">Why You Struggle To Make Money (and 7 Lessons To Change That) <a class="header-anchor" href="#why-you-struggle-to-make-money-and-7-lessons-to-change-that" aria-label="Permalink to &quot;Why You Struggle To Make Money (and 7 Lessons To Change That)&quot;">​</a></h1><p>Dan Koe · 2022-09-03 · <a href="https://thedankoe.com/letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/why-you-struggle-to-make-money-and-7-lessons-to-change-that">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/ijU4OTfzu8Y?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>Money is a problem.</p><p>Everyone knows it.</p><p>Nobody can escape the desire to hop on the latest “get rich quick” advice like winning stocks, shitcoins, and anything else that promises some quick cash.</p><p>It impacts the entirety of our lives.</p><ul><li>The food we have access to</li><li>The environment we can live in</li><li>The people we can connect with</li><li>The amount of stress a situation will cause</li></ul><p>And those all circle back, affecting our ability to make money in the first place.</p><p>Not to mention:</p><p>99% of people aren’t aware of what’s possible.</p><p>Since we were young, and with a blank slate of a mind, we’ve been filled with non-sense that we accept as fact.</p><p>It hurts to realize this, but the one thing holding you back from making as much money as you want is <em>you.</em></p><ul><li>Your thoughts shape your reality.</li><li>Your beliefs dictate how you perceive those thoughts.</li><li>Your perception determines how you act in the world.</li></ul><p>If you don’t believe you can make a million bucks, will the sea of opportunities that you are swimming in even register in your awareness? Or will your perception prevent you from seeing what’s right in front of you?</p><p>None of this is easy, but who said it was supposed to be?</p><p>I’ll answer that for ya,</p><p><em>You.</em></p><h2 id="the-stress-society" tabindex="-1">The Stress Society <a class="header-anchor" href="#the-stress-society" aria-label="Permalink to &quot;The Stress Society&quot;">​</a></h2><p>What causes stress?</p><p><a href="https://thedankoe.com/why-you-always-feel-overwhelmed/" target="_blank" rel="noreferrer">Focus</a>.</p><p>That is, where your attention is placed. The contents of your consciousness.</p><p>Is it split and narrow? Distracted? Hyper-focused on what’s happened, what’s going to happen, and what’s not happening?</p><p>Or is it singular and wide?</p><p>Are you seeing the tip of the iceberg? Or what’s underneath?</p><p>Survival. That’s what’s underneath.</p><p>Every. Single. Action you take is out of the need for survival.</p><p>Not physical survival like the old days.</p><p>I’m talking survival of the self.</p><p>What is the self? It’s an illusion.</p><p>Our mind started as a blank slate.</p><p>As we aged, we created the self with our mind.</p><p>You see, the self only exists when hundreds of thousands of external relationships are formed over time.</p><p>“My name is Dan” is a relationship between me and everyone I come across.</p><p>If no other “selves” existed, why in the world would I call myself “Dan”? Why would I need to speak a certain language? Or words at all?</p><p>If a specific religion, ideology, cultural norm, expectation, opinion, belief, bias, or word hadn’t registered in your awareness, would it even exist to you?</p><p>Think of the self as a bunch of tiny dots that form the shape of a human. Imagine that the dots are connected to strings.</p><p>What happens when one of those strings is plucked, gripped, or threatened?</p><p>Stress response. No matter how small (yet compounding).</p><p>Our attention is sucked back to more pressing matters. The survival of the self. An attempt to prevent the death of one string we’ve attached to our identity.</p><p>“Okay, Dan, cool story bro. How does this relate to making me some cold hard cash??”</p><p>You tell me…</p><p><strong>What happens when you encounter an opportunity to make money?</strong></p><p>I’ll tell you what most people do:</p><ul><li>They misperceive the situation</li><li>They close their mind to seeing beyond what’s in front of them</li><li>They immediately label it as a “scam,” impossible, or not for them</li></ul><p>A survival string is plucked and they shut down to preserve their programmed beliefs. If their beliefs around their ability to make money are threatened, they are threatened.</p><p>Think this leads anywhere beneficial?</p><p>Instead, you must pause, <em>seek</em> to <em>understand</em> every moving piece of the information you receive through observation.</p><p>“Yeah this guy Dan sells a 2 Hour Writer course.”</p><p>2 hours? Lol, you think you can just work for two hours and call it a day?</p><p>Writing? Creativity? You think that’s monetizable? Nobody can do what they love. Back to working for the boss that is doing what he loves!</p><p>(Nobody has said this, but I guarantee some random social media lurkers are thinking it. Eagerly awaiting their chance to leave a negative comment that serves their future in zero possible ways.)</p><p>This is an exaggeration, but can you not see how obvious it is? How people <em>choose</em> what they want to see, stop there, and fill in the rest of the story with assumptions.</p><p>Another example:</p><p><strong>How does it make you feel when you have to talk about money? Or even when it’s brought up?</strong></p><p>Which survival strings are threatened?</p><p>Is it uncomfortable? Do you get mad? Does it immediately make you think to the bill you have to pay when the paycheck deposits on Friday?</p><p>Dive deeper. Consider the possibility. Think critically.</p><p>Money buys freedom in the external world.</p><p>Spirituality returns freedom in the internal world.</p><p>We will discuss survival again under a different lens, because life is more than just money, of course.</p><p>But for a majority of the population, money would decrease the amount of stress they experience by ~80%.</p><p>Solving your money problems opens up room for relaxation, creativity, and solving the deeper, internal problems that lead to true happiness.</p><p>And… it just feels good to fend for yourself, but why?</p><p>The molecule of More, dopamine, rewards you like it did our ancestors when they had to hunt.</p><p>Like how a monkey will get a dopamine response when a light bulb goes off (that signals it will get food) rather than no dopamine response when it gets the same food at the same time.</p><p>Our psyche is wired for entrepreneurship.</p><p>That is, our psyche is wired to be rewarded for the novelty, anticipation, and unpredictability that comes from hunting for our survival. That is how you leverage dopamine in a useful way</p><h2 id="_7-practical-money-lessons-that-will-make-you-infinite-x-more-than-a-college-degree" tabindex="-1">7 Practical Money Lessons That Will Make You [infinite]X More Than A College Degree <a class="header-anchor" href="#_7-practical-money-lessons-that-will-make-you-infinite-x-more-than-a-college-degree" aria-label="Permalink to &quot;7 Practical Money Lessons That Will Make You \\[infinite\\]X More Than A College Degree&quot;">​</a></h2><p>Abstractions on survival are fun to talk about, they help with self-understanding, but how do you implement those teachings?</p><p>By holding them in your awareness as you improve your money situation.</p><p>As you go through these lessons, notice when you feel a negative thought, emotion, or feeling come into your awareness. Question it.</p><h3 id="_1-the-man-in-the-arena" tabindex="-1">1) The Man In The Arena <a class="header-anchor" href="#_1-the-man-in-the-arena" aria-label="Permalink to &quot;1) The Man In The Arena&quot;">​</a></h3><p>Making money is a skill, not a talent.</p><p>Skills are refined with practice.</p><p>How do you practice making money?</p><p>Well, it’s not like a sport where you can get a few of your buddies and still reach the end goal: scoring a point.</p><p>With money, you have to step into the arena.</p><p>The exchange of money is not a battle, but if you don’t have an “opponent” (that has money to give) on the other side of the arena, you aren’t giving yourself a fighting chance.</p><p>Nobody to give you money = no real-world use of your skills = no money being put in your pockets.</p><p>It is not, and should not, just appear out of thin air and into your bank account. Your psyche is wired to hunt. Not to be a monkey collecting bananas in his virtual banana stash with zero effort.</p><p>This is why so many have money problems. They love talking about money, especially in a negative light, but when it comes time to make more? Crickets. That would mean they have to do something uncomfortable. Criticism is the loudest from the bleachers. Booooo!</p><p><em>Studying courses on how to make money is not making money.</em></p><p><em>Building a product, website, or app to make money is not making money.</em></p><blockquote><p>Learn to sell. Learn to build. If you can do both, you will be unstoppable.</p><p>— Naval (@naval) <a href="https://twitter.com/naval/status/1002104154737684480?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 31, 2018</a></p></blockquote><p>You have to build, <em>and sell.</em></p><h3 id="_2-open-your-mind" tabindex="-1">2) Open Your Mind <a class="header-anchor" href="#_2-open-your-mind" aria-label="Permalink to &quot;2) Open Your Mind&quot;">​</a></h3><p>People are slaves to money because they believe they are incapable of making more.</p><p><em>“I didn’t go to college, I can’t get a high paying job.”</em></p><p><em>“Writing? Don’t you have to be like a poet to do that?</em>“</p><p><em>“Lol you think that guy</em> <em><strong>really</strong></em> <em>hit $100K this month? What’s the profit? Either way, I’m going to go with… scam!”</em></p><p>People will feed themselves a self-limiting story that narrows their perception to the point of not seeing the infinite opportunities staring them in the face (your phone). Being broke becomes their reality, and their actions follow.</p><h3 id="_3-fundamentals-are-king" tabindex="-1">3) Fundamentals Are King <a class="header-anchor" href="#_3-fundamentals-are-king" aria-label="Permalink to &quot;3) Fundamentals Are King&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>In business, you need 2 things:</p><ol><li><strong>Value</strong>: A product or service that promises a desirable result (and delivers on that promise).</li><li><strong>People</strong>: Well, this is obvious, but often glanced over. You need people to see the value you have to offer if you want to exchange it for money.</li></ol><p>Like with dating.</p><p>If you are valuable, attention-grabbing, and deliver on the value you display but aren’t in an environment with ample people… how can you expect to land a date?</p><p>If you are in an environment (physical or digital) with ample people, but aren’t a person of value… same story.</p><p>If you were to apply the fundamentals to the online landscape, people come from media, just like you’re reading this media right now.</p><p>Media is the frontend of the internet. It’s what captures, holds, and delivers value on attention.</p><p>Writing, speaking, video, audio, design.</p><p>I prefer writing, as it helps you refine your message before you repurpose it for other mediums. Like how this letter will be used as a soft YouTube script.</p><p>If you want to learn an evergreen skill for the digital economy and implement my content ecosystem, check out <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">The 2 Hour Writer</a>.</p><p>Media attracts <em>people</em>, but how do you create, display, and promote the <em>value</em> you have to offer?</p><p>Marketing, sales, influence, persuasion, and building with no-code tools.</p><p>By learning a skill that will help you succeed in either domain (people or value), your skills crossover and complement each other. Especially if you are in the online “arena” with a personal brand.</p><p>Touching back to “opening your mind,” skill acquisition is one way to aid in that.</p><h3 id="_4-the-one-person-business" tabindex="-1">4) The One Person Business <a class="header-anchor" href="#_4-the-one-person-business" aria-label="Permalink to &quot;4) The One Person Business&quot;">​</a></h3><p>The internet has leveled the playing field for what’s possible.</p><blockquote><p>What used to take:\\</p><p>– A few thousand bucks<br> – A team of employees<br> – Years of study and practice\\</p><p>Can now be done with a free software.\\</p><p>You can laser focus on developing a high value skill set to leverage these tools.\\</p><p>It&#39;s cliche, but the opportunity has never been higher.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1565631122825945089?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">September 2, 2022</a></p></blockquote><p>The one-person business is all about maximizing your time freedom, doing what you truly enjoy, and making more than enough money doing it.</p><p>I believe this is the best option for 99% of people. Not dreaming of starting a billion-dollar behemoth of a company and never doing anything about it.</p><p>It’s all about small steps, personal growth, and providing as much value as <em>you</em> can.</p><p>Here’s how you go about it:</p><p><strong>Start a service business.</strong></p><blockquote><p>Study your interests<br> Start a service business<br> Grow an audience<br> Work for free<br> Develop your process<br> Increase prices<br> Repeat 5-6<br> Productize your process\\</p><p>This takes 2 years for potential $50K+ months &amp; 3 hour workdays\\</p><p>College takes 4 years for potential $10K months &amp; 9 hour workdays</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1480875904104599553?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">January 11, 2022</a></p></blockquote><p>If you can’t leverage money or an audience to send <em>people</em> to a product. Start with a service.</p><p>Why?</p><p>Because you can cold email, cold DM, or create a strategy to get in front of more people on social media.</p><p>And, because it is easier (yes, easier) to sell a more expensive service with direct response marketing, sales, and a proper cold outreach strategy.</p><p>Now, would you be able to create an income for yourself in a few months by trying to sell a low cost <em>product</em> in the DMs?</p><p>No, you need more money, results, and authority before you can sell a product through your brand.</p><p>But with the right strategy, you can land 4+ $2500 clients through DMs and email alone.</p><p><strong>Build an audience on the side.</strong></p><p>You don’t want to be sending cold DMs forever. It only makes sense to build leverage in the form of an audience.</p><p>What do you talk about? Actionable advice related to the service you are selling.</p><p><em>If you sell health coaching, talk about health.</em></p><p><em>If you sell marketing services, talk about marketing.</em></p><p><em>If you sell accounting services, talk about money.</em></p><p>This will establish authority, put you on the radar of hundreds of thousands of people, and expand your network.</p><p>Think about it, you don’t only have direct access to your audience, <em>you have indirect access to every audience of people that follow you</em>_._</p><p>Take a moment to think about that. It’s actually nuts.</p><p><strong>Productize once you have results.</strong></p><p>Now that we’ve gotten results for our clients and built an audience talking about our expertise, it’s time to productize.</p><p>Create a product with the exact system and actions you take with your service business on a daily basis.</p><p>You can use your client testimonials for initial social proof during your launch.</p><p>This letter is already getting very long, so I’m going to leave the one-person business for an entirely separate letter.</p><p><em>If you want 180+ strategies, trainings, and step-by-step roadmaps for building a one-person business (and high-performance mind), check out Modern Mastery. <a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Readers can join for $5.</a></em></p><h3 id="_5-think-big-act-small" tabindex="-1">5) Think Big, Act Small <a class="header-anchor" href="#_5-think-big-act-small" aria-label="Permalink to &quot;5) Think Big, Act Small&quot;">​</a></h3><blockquote><p>When you’re lost, try everything and see what sticks.\\</p><p>When you’re overwhelmed, drop everything and see what sticks.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1565268731017699328?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">September 1, 2022</a></p></blockquote><p>Opening your mind to the potential of being rich is the first step to becoming rich.</p><p>Riches demand a balance of creativity and productivity.</p><p>Creativity demands an open mind and meta-perspective.</p><p>Productivity demands a clear mind and narrow focus.</p><p>Creativity is like you are floating in space. The stars are ideas that register in your awareness. Profitable solutions are created when you create constellations, connections between the stars.</p><p>Productivity is like you’re on a rocket ship to the moon. There is no thought. It is calculated, planned, and foolproof. You cut through the air and arrive at your destination in record time… because the outcome was already decided.</p><p>Creativity is about connection, productivity is about clarity.</p><p>Schedule dedicated time for both.</p><p>You can use my <a href="https://thedankoe.com/the-3-part-daily-routine-for-maximum-productivity/" target="_blank" rel="noreferrer">Fill Empty Use</a> framework to find your own balance.</p><h3 id="_6-increase-baseline-income-maintain-baseline-lifestyle" tabindex="-1">6) Increase Baseline Income, Maintain Baseline Lifestyle <a class="header-anchor" href="#_6-increase-baseline-income-maintain-baseline-lifestyle" aria-label="Permalink to &quot;6) Increase Baseline Income, Maintain Baseline Lifestyle&quot;">​</a></h3><p>In solopreneurship, everything is unpredictable. (This is a good thing)</p><p>Sure, you can create a membership or other recurring monthly offer that can create some stability… but the point is, you will have both high and low months.</p><p>I hit my first $100K month last week.</p><p>I’m not going to hit that this month unless I actively try, but I need to rest.</p><p>That being said, hitting $100K means that my baseline has increased.</p><p>This seems to always happen after a period of tactical stress.</p><blockquote><p>Tactical stress:\\</p><p>The conscious decision to put yourself in a do or die situation – knowing that you have the skill to make it work – and will accept nothing less than success.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1525117916538097666?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 13, 2022</a></p></blockquote><p>I will force myself to launch a product or promotion, make it public, and have to get it done or else I would be a public failure.</p><p>I’ve done this once a year, and I would attribute a majority of my growth to it. Most people get stuck in dreamland and never publish the project they’ve been building.</p><p>That being said, lifestyle creep can be a real thing.</p><p>You’ll hit a high month, something you never could’ve imagined, and celebrate by making a big purchase.</p><p>Meaning, you increased your baseline lifestyle demands.</p><p>More stuff = more responsibility = more resources being utilized = less resources to go towards business = lower monthly income = difficulty sustaining that lifestyle.</p><p>If your lifestyle demands increases with your income, you’re not going to have a good time.</p><h3 id="_7-leverage-your-time-then-your-mind" tabindex="-1">7) Leverage Your Time, Then Your Mind <a class="header-anchor" href="#_7-leverage-your-time-then-your-mind" aria-label="Permalink to &quot;7) Leverage Your Time, Then Your Mind&quot;">​</a></h3><blockquote><p>Earn with your mind, not with your time.</p><p>— Naval (@naval) <a href="https://twitter.com/naval/status/1206967499838803968?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">December 17, 2019</a></p></blockquote><p>Manual labor implies that there is a limit on how much you can work, meaning there is a limit on how much you can make.</p><p>The highest-paid earners are the strategists, visionaries, and innovators of the world.</p><p>Yes, even if they don’t start a billion-dollar company.</p><p>A $1M/year one-person business demands creativity, leverage, and productization.</p><p>My goal is to have products and digital real estate in place to the point where I can spend ALL of my time writing. No-code tools, automations, and social media handles the rest.</p><p>Unless you have ample cash flow to invest in audience growth or traffic acquisition (people) you’re going to have to spend time building that cash flow with a service business.</p><p>Once you’ve built digital leverage through audience growth, have gotten results with your service, and are ready to productize… that’s where the real fun begins.</p><p>Most people get stuck in the feast or famine client business because they don’t use their mind. They don’t realize the value of digital leverage, don’t grow, and spend their time in an endless cycle of cold DMs and emails.</p><p>Build an audience. Build an email list. Build a list of buyers.</p><blockquote><p>Build distribution, then build whatever you want.</p><p>— Jack Butcher (@jackbutcher) <a href="https://twitter.com/jackbutcher/status/1395945544430854144?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 22, 2021</a></p></blockquote><p>That’s digital leverage. Once they’re big enough, build whatever you want.</p><p>That’s all for this letter.</p><p>If you enjoyed it, you’ll enjoy what happened this week off of surface-level social media (below).</p><p>Dan Koe</p><p><strong>What Happened This Week</strong></p><p>We’re still getting some incredible feedback from the 2 Hour Writer. People are growing from Instagram reels and TikToks with writing (yes, you read that correctly), writing incredible newsletters that build authority, and having a content ecosystem that separates you from the sea of new creators.</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">Check out 2HW here.</a></p><p>Inside Modern Mastery we had a brand workshop. We broke down Based Realists profile, threw in some profile design education for getting maximum followers, and answered questions.</p><p>Joey posted the Creator Tech Stack going over the best software to start your one-person creator business (if you’re looking to break into this space).</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Readers can get access to both (and more) for $5 here.</a></p><p>As always, YouTube will be up later. Podcast is starting back up soon. Keep an eye on those if you’re interested.</p>',188)])])}const g=o(r,[["render",s]]);export{y as __pageData,g as default};
